alter table submission_feedback add column if not exists timecode_seconds integer, add column if not exists screenshot_path text, add column if not exists audience text not null default 'team', add column if not exists checklist_built boolean not null default false; do $$ begin alter table public.submission_feedback add constraint submission_feedback_audience_check check (audience in ('team', 'client')); exception when duplicate_object then null; end $$; create index if not exists submission_feedback_audience_idx on submission_feedback (submission_id, audience, created_at); drop policy if exists "submission_feedback: videographer reply own" on submission_feedback; create policy "submission_feedback: videographer reply own" on submission_feedback for insert with check ( public.current_role() = 'videographer' and public.owns_submission(submission_id) and author_id = auth.uid() ); drop policy if exists "submission_feedback: client read shared" on submission_feedback; create policy "submission_feedback: client read shared" on submission_feedback for select using ( public.current_role() = 'client' and audience = 'client' and exists ( select 1 from public.submissions s where s.id = submission_id and s.visibility = 'team_and_client' and s.client_id = public.current_client_id() ) ); drop policy if exists "submission_feedback: client comment shared" on submission_feedback; create policy "submission_feedback: client comment shared" on submission_feedback for insert with check ( public.current_role() = 'client' and audience = 'client' and author_id = auth.uid() and exists ( select 1 from public.submissions s where s.id = submission_id and s.visibility = 'team_and_client' and s.client_id = public.current_client_id() ) ); create table if not exists submission_checklist ( id uuid primary key default gen_random_uuid(), submission_id uuid not null references submissions (id) on delete cascade, feedback_id uuid references submission_feedback (id) on delete cascade, version integer, text text not null, done boolean not null default false, done_at timestamptz, source text not null default 'team', created_at timestamptz not null default now() ); create index if not exists submission_checklist_submission_idx on submission_checklist (submission_id, done, created_at); alter table submission_checklist enable row level security; drop policy if exists "submission_checklist: management" on submission_checklist; create policy "submission_checklist: management" on submission_checklist for all using ( public.current_role() in ('ceo', 'operations_manager', 'staff') and ( public.is_ceo_role() or exists ( select 1 from public.submissions s where s.id = submission_id and s.client_id is not null and public.can_see_client(s.client_id) ) ) ) with check ( public.current_role() in ('ceo', 'operations_manager', 'staff') and ( public.is_ceo_role() or exists ( select 1 from public.submissions s where s.id = submission_id and s.client_id is not null and public.can_see_client(s.client_id) ) ) ); drop policy if exists "submission_checklist: videographer own read" on submission_checklist; create policy "submission_checklist: videographer own read" on submission_checklist for select using (public.current_role() = 'videographer' and public.owns_submission(submission_id)); drop policy if exists "submission_checklist: videographer tick own" on submission_checklist; create policy "submission_checklist: videographer tick own" on submission_checklist for update using (public.current_role() = 'videographer' and public.owns_submission(submission_id)) with check (public.current_role() = 'videographer' and public.owns_submission(submission_id)); drop policy if exists "submission_checklist: videographer add own" on submission_checklist; create policy "submission_checklist: videographer add own" on submission_checklist for insert with check ( public.current_role() = 'videographer' and public.owns_submission(submission_id) and feedback_id is null ); create or replace function public.keep_checklist_text() returns trigger language plpgsql security definer set search_path = public as $$ begin if public.current_role() = 'videographer' then new.text := old.text; new.feedback_id := old.feedback_id; new.source := old.source; new.version := old.version; new.submission_id := old.submission_id; end if; return new; end; $$; drop trigger if exists submission_checklist_pin on submission_checklist; create trigger submission_checklist_pin before update on submission_checklist for each row execute procedure public.keep_checklist_text(); create or replace function public.build_checklist_from_feedback() returns trigger language plpgsql security definer set search_path = public as $$ declare submission_owner uuid; chunk text; cleaned text; parts text[]; made integer := 0; begin select created_by into submission_owner from public.submissions where id = new.submission_id; if submission_owner is not null and new.author_id = submission_owner then return new; end if; if new.body is null or btrim(new.body) = '' then return new; end if; if position(e'\n' in new.body) > 0 then parts := regexp_split_to_array(new.body, e'\n'); elsif length(new.body) > 180 then parts := regexp_split_to_array( regexp_replace(new.body, '([.!?])\s+', e'\\1\n', 'g'), e'\n' ); else parts := array[new.body]; end if; foreach chunk in array parts loop cleaned := btrim(regexp_replace(chunk, '^\s*([-*•–]|\d+[.)])\s*', '')); if length(cleaned) < 3 then continue; end if; insert into public.submission_checklist (submission_id, feedback_id, version, text, source) values (new.submission_id, new.id, new.version, cleaned, new.audience); made := made + 1; end loop; if made > 0 then update public.submission_feedback set checklist_built = true where id = new.id; end if; return new; end; $$; drop trigger if exists submission_feedback_checklist on submission_feedback; create trigger submission_feedback_checklist after insert on submission_feedback for each row execute procedure public.build_checklist_from_feedback(); create table if not exists client_assets ( id uuid primary key default gen_random_uuid(), client_id uuid not null references clients (id) on delete cascade, submission_id uuid references submissions (id) on delete set null, kind text not null default 'link' check (kind in ('link', 'file')), title text not null, url text, storage_path text, mime_type text, size_bytes bigint, notes text, visibility text not null default 'team' check (visibility in ('team', 'team_and_client')), uploaded_by uuid references profiles (id) on delete set null, created_at timestamptz not null default now() ); create index if not exists client_assets_client_idx on client_assets (client_id, created_at desc); create index if not exists client_assets_submission_idx on client_assets (submission_id); alter table client_assets enable row level security; drop policy if exists "client_assets: team on the client" on client_assets; create policy "client_assets: team on the client" on client_assets for all using (public.can_see_client(client_id)) with check (public.can_see_client(client_id)); drop policy if exists "client_assets: client read shared" on client_assets; create policy "client_assets: client read shared" on client_assets for select using ( public.current_role() = 'client' and visibility = 'team_and_client' and client_id = public.current_client_id() ); drop policy if exists "client_assets: client upload own" on client_assets; create policy "client_assets: client upload own" on client_assets for insert with check ( public.current_role() = 'client' and client_id = public.current_client_id() and visibility = 'team_and_client' and uploaded_by = auth.uid() ); drop policy if exists "client_assets: client delete own" on client_assets; create policy "client_assets: client delete own" on client_assets for delete using ( public.current_role() = 'client' and client_id = public.current_client_id() and uploaded_by = auth.uid() ); insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ( 'feedback-shots', 'feedback-shots', false, 5242880, array['image/png', 'image/jpeg', 'image/webp', 'image/gif', 'image/heic'] ) on conflict (id) do update set file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types, public = false; insert into storage.buckets (id, name, public, file_size_limit) values ('upload-assets', 'upload-assets', false, 10485760) on conflict (id) do update set file_size_limit = excluded.file_size_limit, public = false; drop policy if exists "feedback-shots: team on the client" on storage.objects; create policy "feedback-shots: team on the client" on storage.objects for all using ( bucket_id = 'feedback-shots' and public.can_see_client(public.storage_path_client_id(name)) ) with check ( bucket_id = 'feedback-shots' and public.can_see_client(public.storage_path_client_id(name)) ); drop policy if exists "feedback-shots: client own" on storage.objects; create policy "feedback-shots: client own" on storage.objects for all using ( bucket_id = 'feedback-shots' and public.current_role() = 'client' and public.storage_path_client_id(name) = public.current_client_id() ) with check ( bucket_id = 'feedback-shots' and public.current_role() = 'client' and public.storage_path_client_id(name) = public.current_client_id() ); drop policy if exists "upload-assets: team on the client" on storage.objects; create policy "upload-assets: team on the client" on storage.objects for all using ( bucket_id = 'upload-assets' and public.can_see_client(public.storage_path_client_id(name)) ) with check ( bucket_id = 'upload-assets' and public.can_see_client(public.storage_path_client_id(name)) ); drop policy if exists "upload-assets: client own" on storage.objects; create policy "upload-assets: client own" on storage.objects for all using ( bucket_id = 'upload-assets' and public.current_role() = 'client' and public.storage_path_client_id(name) = public.current_client_id() ) with check ( bucket_id = 'upload-assets' and public.current_role() = 'client' and public.storage_path_client_id(name) = public.current_client_id() ); create or replace function public.notify_new_version() returns trigger language plpgsql security definer set search_path = public as $$ declare parent record; client_name text; recipient uuid; begin select s.id, s.title, s.client_id, s.created_by into parent from public.submissions s where s.id = new.submission_id; if parent.id is null then return new; end if; select name into client_name from public.clients where id = parent.client_id; for recipient in select p.id from public.profiles p where p.role = 'ceo' union select cs.staff_id from public.client_staff cs join public.profiles p on p.id = cs.staff_id where cs.client_id = parent.client_id and p.role in ('operations_manager', 'staff') loop perform public.notify_user( recipient, 'upload_new_version', case when new.version = 1 then 'New upload: ' || parent.title else 'New cut (v' || new.version || '): ' || parent.title end, concat_ws(' · ', client_name, 'ready to review'), '/app/uploads' ); end loop; return new; end; $$; drop trigger if exists submission_versions_notify on submission_versions; create trigger submission_versions_notify after insert on submission_versions for each row execute procedure public.notify_new_version(); create or replace function public.notify_feedback() returns trigger language plpgsql security definer set search_path = public as $$ declare parent record; client_name text; recipient uuid; preview text; begin select s.id, s.title, s.client_id, s.created_by into parent from public.submissions s where s.id = new.submission_id; if parent.id is null then return new; end if; select name into client_name from public.clients where id = parent.client_id; preview := case when length(new.body) > 90 then left(new.body, 87) || '…' else new.body end; perform public.notify_user( parent.created_by, 'upload_feedback', 'Feedback on ' || parent.title, preview, '/app/uploads' ); if new.audience = 'client' then for recipient in select p.id from public.profiles p where p.role = 'ceo' union select cs.staff_id from public.client_staff cs join public.profiles p on p.id = cs.staff_id where cs.client_id = parent.client_id and p.role in ('operations_manager', 'staff') loop perform public.notify_user( recipient, 'upload_client_feedback', 'Client comment on ' || parent.title, concat_ws(' · ', client_name, preview), '/app/uploads' ); end loop; end if; return new; end; $$; drop trigger if exists submission_feedback_notify on submission_feedback; create trigger submission_feedback_notify after insert on submission_feedback for each row execute procedure public.notify_feedback(); create or replace function public.notify_submission_shared() returns trigger language plpgsql security definer set search_path = public as $$ declare recipient uuid; begin if new.visibility is not distinct from old.visibility then return new; end if; if new.visibility <> 'team_and_client' then return new; end if; for recipient in select id from public.profiles where role = 'client' and client_id = new.client_id loop perform public.notify_user( recipient, 'upload_shared', 'New video ready to watch', '“' || new.title || '” is on your Uploads tab.', '/app/portal/uploads' ); end loop; return new; end; $$; drop trigger if exists submissions_shared_notify on submissions; create trigger submissions_shared_notify after update on submissions for each row execute procedure public.notify_submission_shared(); create or replace function public.notify_asset_added() returns trigger language plpgsql security definer set search_path = public as $$ declare recipient uuid; actor_role text; client_name text; begin actor_role := public.current_role(); select name into client_name from public.clients where id = new.client_id; if actor_role = 'client' then for recipient in select p.id from public.profiles p where p.role = 'ceo' union select cs.staff_id from public.client_staff cs join public.profiles p on p.id = cs.staff_id where cs.client_id = new.client_id and p.role in ('operations_manager', 'staff', 'videographer') loop perform public.notify_user( recipient, 'asset_added', 'New material from ' || coalesce(client_name, 'a client'), new.title, '/app/uploads' ); end loop; elsif new.visibility = 'team_and_client' then for recipient in select id from public.profiles where role = 'client' and client_id = new.client_id loop perform public.notify_user( recipient, 'asset_added', 'New material on your project', new.title, '/app/portal/uploads' ); end loop; end if; return new; end; $$; drop trigger if exists client_assets_notify on client_assets; create trigger client_assets_notify after insert on client_assets for each row execute procedure public.notify_asset_added();
